#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_pop_shrink_even_capacity(void) {
    DArrayStack *stack = NULL;
    int success = 0;
    int popped_value = 0;

    // Create a stack with even capacity (e.g., 4) and fill it to just above half capacity threshold.
    // The shrink condition: capacity % 2 == 0 AND capacity >= 2 AND top <= (capacity/2) - 1.
    // For capacity = 4, threshold is (4/2)-1 = 1.
    // We need top <= 1 after the pop to trigger shrink.
    // Let's start with top = 2 (3 elements). After pop, top becomes 1, which triggers shrink.
    stack = create_stack(4);
    TEST_ASSERT_NOT_NULL(stack);

    // Push three elements: top will be 2 (indices 0,1,2).
    int push_result = push(stack, 100);
    TEST_ASSERT_EQUAL_INT(0, push_result); // top becomes 0
    push_result = push(stack, 200);
    TEST_ASSERT_EQUAL_INT(1, push_result); // top becomes 1
    push_result = push(stack, 300);
    TEST_ASSERT_EQUAL_INT(2, push_result); // top becomes 2

    // Verify initial state
    TEST_ASSERT_EQUAL_INT(4, stack->capacity);
    TEST_ASSERT_EQUAL_INT(2, stack->top);

    // Now pop one element. After pop, top becomes 1, which is <= (4/2)-1 = 1.
    // This should trigger shrink_array.
    popped_value = pop(stack, &success);

    // Assertions for path 13:
    // success pointer is not NULL, so *success should be set to 1.
    TEST_ASSERT_EQUAL_INT(1, success);
    // The popped value should be the last pushed (300).
    TEST_ASSERT_EQUAL_INT(300, popped_value);
    // Top should be decremented to 1.
    TEST_ASSERT_EQUAL_INT(1, stack->top);
    // The element at old top (index 2) should be zeroed (implementation sets to 0).
    TEST_ASSERT_EQUAL_INT(0, stack->arrPtr[2]);
    // The shrink_array should have been called. We cannot directly assert its effect
    // because it's a dependency, but we can verify that capacity may have changed.
    // According to shrink_array implementation, new capacity = old capacity / 2 = 2.
    // However, shrink_array may fail (return NULL) if malloc fails, but we assume success.
    // We'll check that capacity is now 2 (if shrink succeeded) or remains 4 (if shrink failed).
    // Since we are not mocking malloc failure, we assume shrink succeeds.
    // We'll use show_capacity to verify.
    int new_capacity = show_capacity(stack);
    // The shrink_array should have succeeded, so capacity should be 2.
    TEST_ASSERT_EQUAL_INT(2, new_capacity);

    // Cleanup
    free_stack(stack);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_pop_shrink_even_capacity);
    return UNITY_END();
}

