// Asserts that two stacks have equal contents using stacks_equal function
void helper_assert_stack_equal(DArrayStack *stack1, DArrayStack *stack2) {
    int result = stacks_equal(stack1, stack2);
    TEST_ASSERT_EQUAL_INT(1, result);
}

// Asserts that a stack has the expected capacity
void helper_assert_stack_capacity(DArrayStack *stack, int expected_capacity) {
    int actual_capacity = show_capacity(stack);
    TEST_ASSERT_EQUAL_INT(expected_capacity, actual_capacity);
}

// Asserts that a stack has the expected number of elements
void helper_assert_stack_size(DArrayStack *stack, int expected_size) {
    int actual_size = stack_size(stack);
    TEST_ASSERT_EQUAL_INT(expected_size, actual_size);
}

// Asserts that a stack is empty (or NULL)
void helper_assert_stack_empty(DArrayStack *stack) {
    int empty = isempty(stack);
    TEST_ASSERT_EQUAL_INT(1, empty);
}

// Asserts that a stack contains a specific value
void helper_assert_stack_contains(DArrayStack *stack, int value) {
    int contains = stack_contains(stack, value);
    TEST_ASSERT_EQUAL_INT(1, contains);
}

// Asserts that the top element of a stack matches the expected value
void helper_assert_stack_peek(DArrayStack *stack, int expected_value) {
    int success = 0;
    TEST_ASSERT_NOT_NULL(stack);
    int top_value = peek(stack, &success);
    TEST_ASSERT_EQUAL_INT(1, success);
    TEST_ASSERT_EQUAL_INT(expected_value, top_value);
}

// Asserts that popping from a stack returns the expected value and updates stack correctly
void helper_assert_stack_pop(DArrayStack *stack, int expected_value) {
    int success = 0;
    int popped_value = pop(stack, &success);
    TEST_ASSERT_EQUAL_INT(1, success);
    TEST_ASSERT_EQUAL_INT(expected_value, popped_value);
}

// Asserts that the string representation of a stack matches the expected string
void helper_assert_stack_to_string(DArrayStack *stack, const char *expected_string) {
    int buffer_size = 256;
    char *buffer = malloc(buffer_size * sizeof(char));
    int result = stack_to_string(stack, buffer, buffer_size);
    TEST_ASSERT_NOT_EQUAL_INT(-1, result);
    TEST_ASSERT_EQUAL_STRING(expected_string, buffer);
    free(buffer);
}

// ========== Created - Utility Operations ==========

// Creates a stack and pushes an array of values onto it
DArrayStack *helper_create_stack_with_values(int *values, int size, int initial_capacity) {
    DArrayStack *stack = create_stack(initial_capacity);
    if (stack == NULL) {
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        push(stack, values[i]);
    }
    return stack;
}

// Creates a stack with random integer values
DArrayStack *helper_create_random_stack(int size, int initial_capacity, int min_value, int max_value) {
    srand(12345); // Use fixed seed for deterministic tests
    DArrayStack *stack = create_stack(initial_capacity);
    if (stack == NULL) {
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        int value = min_value + rand() % (max_value - min_value + 1);
        push(stack, value);
    }
    return stack;
}

// Creates a deep copy of a stack using copy_stack function
DArrayStack *helper_clone_stack(DArrayStack *src) {
    return copy_stack(src);
}

// Clears all elements from a stack without freeing it
void helper_reset_stack(DArrayStack *stack) {
    clear_stack(stack);
}

// Verifies basic stack integrity by checking size <= capacity
void helper_verify_stack_integrity(DArrayStack *stack) {
    if (stack == NULL) {
        return;
    }
    int size = stack_size(stack);
    int capacity = show_capacity(stack);
    TEST_ASSERT_TRUE(size <= capacity);
}

