{
    if (ptr == NULL)
    {
        if (success) *success = 0;
        return 0;
    }
    if (ptr->top == -1)
    {
        if (success) *success = 0;
        return 0;
    }
    if (success) *success = 1;
    int ele = ptr->arrPtr[ptr->top];
    ptr->arrPtr[ptr->top] = 0;
    ptr->top = (ptr->top - 1);
